import {gauge,riverCases,discharge} from './river-data.js?v=20261023-uplands02';
export const riverViews={
 'river-slopes':[['freeze','Freeze–thaw'],['chemical','Chemical'],['roots','Biological'],['slide','Slide'],['slump','Slump']],
 'river-load':[['hydraulic','Hydraulic action'],['abrasion','Abrasion'],['attrition','Attrition'],['solution','Solution'],['traction','Traction'],['saltation','Saltation'],['suspension','Suspension'],['deposition','Deposition']],
 'river-courses':[['upper','Upper course'],['middle','Middle course'],['lower','Lower course'],['long','Long profile']],
 'river-flow':[['base','Base case'],['area','Double area'],['speed','Double speed'],['both','Double both'],['route','Locate the Tees']],
 'river-weather':[['rain','Rain pathways'],['saturated','Saturated ground'],['drought','Drought'],['season','Weather vs climate'],['record','EA stage excerpt']]
};
export const riverAnimated=(kind,view)=>kind!=='river-courses'&&!(kind==='river-flow'&&view==='route')&&!(kind==='river-weather'&&view==='record');
export const riverRequirements=Object.fromEntries(Object.entries(riverViews).map(([k,v])=>[k,v.map(x=>x[0])]));
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const arr=(a,b,c,d)=>`<path d="M${a} ${b}L${c} ${d}" fill="none" stroke="#ef9c88" stroke-width="3" marker-end="url(#riverArrow)"/>`;
const dot=(x,y,r=5,color='#efd1b1')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${color}"/>`;
const channel=(t,y=220)=>`<path d="M20 ${y}Q${70+t*50} ${y-7} 150 ${y}T280 ${y}T420 ${y}V310H20Z" fill="#5b96aa"/><path d="M20 ${y}Q${70+t*50} ${y-7} 150 ${y}T280 ${y}T420 ${y}" fill="none" stroke="#c6e5e9" stroke-width="3"/>`;
export function gaugeTable(teaching=false){return `<figure style="margin:0 0 20px"><figcaption style="font-weight:600;margin-bottom:12px">Environment Agency · Barnard Castle · River Tees</figcaption><table style="width:100%;font-size:13px;border-collapse:collapse"><caption style="text-align:left;margin-bottom:10px">Instantaneous water level (stage), metres</caption><thead><tr><th style="text-align:left;padding:8px">Reported date/time</th><th style="text-align:right;padding:8px">Stage (m)</th></tr></thead><tbody>${gauge.observations.map(o=>`<tr><td style="padding:8px;border-top:1px solid #9baeb4">${o.date}</td><td style="text-align:right;padding:8px;border-top:1px solid #9baeb4">${o.value.toFixed(3)}</td></tr>`).join('')}</tbody></table><p style="font-size:12px;line-height:1.7">Two historical values transcribed from <a href="${gauge.source}" target="_blank" rel="noopener" style="color:inherit">EA station F3504</a>, checked 23 October 2026. Environment Agency data, <a href="https://www.nationalarchives.gov.uk/doc/open-government-licence/version/3/" target="_blank" rel="noopener" style="color:inherit">Open Government Licence v3</a>.${teaching?' Not a live reading, continuous hydrograph or discharge record. Stage is relative to a gauge datum; these values alone do not establish event causes.':''}</p></figure>`;}
export function riverScene(kind,selected,t=0){const options=riverViews[kind];if(!options)return '';const s=options.some(v=>v[0]===selected)?selected:options[0][0];t=Math.max(0,Math.min(1,Number(t)||0));if(!riverAnimated(kind,s))t=0;let b='',caption='';
 if(kind==='river-weather'&&s==='record')return `<div style="color:#eaf0f1">${gaugeTable(true)}</div>`;
 if(kind==='river-slopes'){
  const slump=s==='slump',slide=s==='slide';b='<path d="M20 95H180L295 255H420V315H20Z" fill="url(#rRock)"/>'+channel(t,270)+tx(25,45,'Valley side → channel · conceptual section');
  if(slide||slump){b+=`<path d="${slump?'M120 95Q115 210 270 255':'M135 95L270 255'}" fill="none" stroke="#ef9c88" stroke-width="3" stroke-dasharray="6 5"/><g transform="translate(${t*50} ${slump?60*t-15*t*t:60*t}) rotate(${slump?-t*20:0} 140 110)"><path d="M140 95H180L225 160 175 150Z" fill="#dfbaa2" stroke="#ecdfcd" stroke-width="2"/></g>`+arr(295,125,330,205)+tx(300,110,'Gravity',12);caption=slump?'A mass rotates along a curved slip surface into the valley. The channel can later carry supplied material away.':'A mass slides along a broadly planar surface. This is gravity-driven transfer, not a grain bouncing in river flow.';}
  else{b+=`<path d="M105 95L${110+Math.sin(t*3.14)*6} 140 95 165 140 190" stroke="${s==='freeze'?'#b9e3ec':'#344c58'}" stroke-width="${s==='freeze'?5+Math.sin(t*3.14)*7:5}" fill="none"/>`;
   if(s==='roots')b+=`<path d="M110 90V${120+t*55}m0-20l-20 15m20-35l20 10" stroke="#bad2a4" stroke-width="5" fill="none"/>`;if(s==='chemical')for(let i=0;i<6;i++)b+=dot(108+i*3,105+(t*80+i*12)%80,3,'#b7e5ed');caption={freeze:'Repeated freeze–thaw can widen cracks: mechanical weathering in place. Expansion is exaggerated; times are compressed.',chemical:'Water reacts with susceptible minerals: chemical weathering. Subsequent removal or dissolved transport is a separate stage.',roots:'Roots grow into weaknesses: biological weathering. Breakdown can supply material that later moves downslope or downstream.'}[s];}
 }
 if(kind==='river-load'){
  b=channel(t,100)+'<path d="M20 280H420V315H20Z" fill="url(#rRock)"/>'+tx(25,45,'SIDE VIEW · flowing water →')+arr(50,75,300,75);
  if(s==='abrasion'||s==='hydraulic'){b+='<path d="M320 105H420V280H320V205L345 180 320 155Z" fill="url(#rRock)"/>';
   if(s==='abrasion')for(let i=0;i<5;i++)b+=dot(60+(t*230+i*30)%260,175+i*15,6);else b+=`<path d="M320 180L${345+Math.sin(t*3.14)*12} 175 365 150" stroke="#c6e5e9" stroke-width="${3+Math.sin(t*3.14)*7}" fill="none"/>`;caption=s==='abrasion'?'Sediment strikes or scrapes bed and banks. Compare this channel target with particle-to-particle attrition.':'Water force exploits a weakness in the bank. Crack opening is exaggerated and is not a calibrated erosion rate.';}
  else if(s==='attrition'){b+=dot(135+Math.sin(t*3.14)*65,200,18)+dot(300-Math.sin(t*3.14)*65,200,18)+tx(45,130,'Particle collisions → smaller / rounder');caption='Attrition wears the load itself during collisions; it is distinct from abrasion of the channel.';}
  else if(s==='solution'){b+=tx(60,185,'Dissolved substances · no solid grains',15)+arr(70,225,350,225);caption='Dissolved load travels in solution. It is not the same as fine solid particles in suspension.';}
  else{for(let i=0;i<7;i++){const x=40+(t*300+i*48)%350,y=s==='traction'?270:s==='saltation'?270-50*Math.abs(Math.sin(t*3*Math.PI+i)):s==='deposition'?150+t*115:165+Math.sin(i+t*4)*14;b+=dot(x,y,s==='traction'?10:s==='suspension'?3:6);}caption={traction:'Large grains roll or slide in contact with the bed: traction.',saltation:'Grains bounce along the bed: saltation.',suspension:'Fine solid particles are carried within the water: suspension.',deposition:'When transport conditions weaken, some particles settle. Other parts of the reach can still carry sediment or erode.'}[s];}
 }
 if(kind==='river-courses'){
  if(s==='long'){b=arr(40,290,405,290)+arr(40,290,40,65)+'<path d="M50 85Q110 210 220 245T400 275" stroke="#bedde4" stroke-width="5" fill="none"/>'+arr(145,200,200,230)+tx(25,40,'LONG PROFILE · height along the course')+tx(50,320,'Source')+tx(335,320,'Mouth')+tx(250,145,'Gradient tends to ease');caption='This long profile follows the course. The arrow indicates downstream direction, not water speed; geometry is invented, not a measured Tees profile.';}
  else{const upper=s==='upper',lower=s==='lower',fl=upper?185:lower?55:110,fr=440-fl,bench=upper?245:lower?205:220,cl=upper?205:lower?150:175,cr=440-cl,bed=upper?268:lower?285:275,top=upper?250:lower?220:235;b=`<path d="M20 80L${fl} ${bench}H${cl}V${bed}H${cr}V${bench}H${fr}L420 80V320H20Z" fill="url(#rRock)"/><path d="M${cl} ${top}H${cr}V${bed}H${cl}Z" fill="#679eb0"/>`+tx(25,40,`${s.toUpperCase()} COURSE · valley cross-profile`)+arr(fl,bench-18,fr,bench-18)+tx(25,315,upper?'Narrow valley · small channel':lower?'Broad valley floor · distinct water channel':'Wider valley · growing channel',13);caption=upper?'Upper-course comparison: narrow steep-sided valley, relatively small channel and important downcutting. Symbolic section, not fixed dimensions.':lower?'Lower-course comparison: broader valley floor and generally wider/deeper channel. Dry valley floor and wetted channel are shown separately.':'Middle-course comparison: valley and channel often enlarge, with lateral erosion and deposition. Local geology and history can alter the pattern.';}
 }
 if(kind==='river-flow'){
  if(s==='route'){b='<path d="M50 80Q140 80 180 155T275 230 395 275" stroke="#a6d6e3" stroke-width="8" fill="none"/>'+dot(50+t*345,80+t*195,7)+tx(25,40,'River Tees · schematic route')+tx(25,65,'Cross Fell / North Pennines',12)+tx(180,130,'Middle reaches',12)+tx(225,305,'North Sea · Hartlepool / Redcar',12);caption='The Tees runs from Cross Fell to the North Sea. This conceptual route is not a surveyed map or precise course; lower reaches include navigation modifications.';}
  else{const c=riverCases[s],q=discharge(c.area,c.speed),w=c.area===16?320:160,left=(440-w)/2;b=tx(25,40,'HYPOTHETICAL REACH · not Tees measurements')+`<path d="M${left} 100H${left+w}V225H${left}Z" fill="#5f96aa" stroke="#bedde6" stroke-width="2"/>`+tx(left+12,130,`Area ${c.area}m²`,16)+tx(35,270,`Mean speed ${c.speed}m/s`,15)+tx(35,305,`Q = ${c.area} × ${c.speed} = ${q}m³/s`,19);for(let i=0;i<(c.area===16?12:6);i++)b+=dot(left+10+((t*c.speed*240+i*43)%(w-20)),155+i%3*22,4,'#e9dfc5');caption=`Controlled comparison: cross-sectional area ${c.area}m²; mean velocity ${c.speed}m/s; discharge ${q}m³/s. Change area or speed separately to isolate its effect. Particle motion is illustrative, not a scale measurement.`;}
 }
 if(kind==='river-weather'){
  if(s==='season'){b=tx(25,40,'Different time scales, different questions')+'<rect x="25" y="90" width="180" height="160" rx="12" fill="#3b586f"/><rect x="225" y="90" width="190" height="160" rx="12" fill="#3b586f"/>'+tx(45,125,'Weather event',17)+tx(45,165,'Storm today',14)+tx(45,195,'Hours / days',13)+tx(245,125,'Climate pattern',17)+tx(245,165,'Seasonality',14)+tx(245,195,'Long-term evidence',13)+channel(t,280);caption='One event is not a climate trend. Seasonal patterns and single storms require evidence at different time scales; no rainfall values are invented in this view.';}
  else{const dry=s==='drought',sat=s==='saturated';b='<path d="M20 95L180 230H260L420 95V320H20Z" fill="url(#rRock)"/>'+`<path d="M${dry?180+25*t:180} 230H${dry?260-25*t:260}V280H${dry?180+25*t:180}Z" fill="#639daf"/>`+tx(25,40,dry?'Prolonged dry conditions':sat?'Rain on already saturated ground':'Rain reaches different pathways');if(!dry){for(let i=0;i<12;i++)b+=`<path d="M${35+i*31} ${70+(t*75+i*7)%75}l-4 10" stroke="#bcdfea" stroke-width="2"/>`;b+=arr(70,145,180,225)+arr(370,145,260,225);if(!sat)b+='<path d="M80 180L110 270 195 270" stroke="#c2b392" stroke-width="3" stroke-dasharray="6 5" fill="none"/>';caption=sat?'Already saturated ground can increase quick runoff and river response. This process model does not predict a flood level or guarantee slope failure.':'Some water runs over the surface while some takes slower subsurface pathways. Storage and travel time can create a lag after rainfall.';}else{b+=arr(190,160,190,90)+arr(245,160,245,90)+tx(25,315,'Reduced input · losses · storage effects',13);caption='Reduced rainfall input and continuing evapotranspiration losses can reduce river flow during a prolonged dry spell. Geology, storage and management affect timing; not every river stops.';}}
 }
 return `<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${caption.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><linearGradient id="rRock" x2="0" y2="1"><stop stop-color="#b4b39e"/><stop offset="1" stop-color="#7d8b83"/></linearGradient><marker id="riverArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#ef9c88"/></marker></defs><g font-family="sans-serif" fill="#edf1ec">${b}</g></svg><p class="geo-caption">${caption}</p>`;
}
